def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not cells:
        return out
    r0 = min(r for r, _ in cells); r1 = max(r for r, _ in cells)
    c0 = min(c for _, c in cells); c1 = max(c for _, c in cells)
    # Dots on a row/column outside the rectangle direct the projection away from themselves.
    for r in range(r0, r1 + 1):
        left = any(grid[r][c] not in (0, 2) for c in range(c0))
        right = any(grid[r][c] not in (0, 2) for c in range(c1 + 1, w))
        if left and not right:
            cols = range(c1 + 1, w)
        elif right and not left:
            cols = range(0, c0)
        else:
            cols = range(w)
        for c in cols:
            if out[r][c] == 0:
                out[r][c] = 2
    for c in range(c0, c1 + 1):
        above = any(grid[r][c] not in (0, 2) for r in range(r0))
        below = any(grid[r][c] not in (0, 2) for r in range(r1 + 1, h))
        if above and not below:
            rows = range(r1 + 1, h)
        elif below and not above:
            rows = range(0, r0)
        else:
            rows = range(h)
        for r in rows:
            if out[r][c] == 0:
                out[r][c] = 2
    return out
