def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    # Extend each rectangle row away from any marker lying outside its left/right edge.
    for r in range(r0, r1 + 1):
        left_mark = any(grid[r][c] not in (0, 2) for c in range(c0))
        right_mark = any(grid[r][c] not in (0, 2) for c in range(c1 + 1, w))
        if not left_mark:
            for c in range(c0):
                if out[r][c] == 0: out[r][c] = 2
        if not right_mark:
            for c in range(c1 + 1, w):
                if out[r][c] == 0: out[r][c] = 2
    # Extend each rectangle column away from any marker lying above/below it.
    for c in range(c0, c1 + 1):
        top_mark = any(grid[r][c] not in (0, 2) for r in range(r0))
        bottom_mark = any(grid[r][c] not in (0, 2) for r in range(r1 + 1, h))
        if not top_mark:
            for r in range(r0):
                if out[r][c] == 0: out[r][c] = 2
        if not bottom_mark:
            for r in range(r1 + 1, h):
                if out[r][c] == 0: out[r][c] = 2
    return out
